def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')

    # If opponent never cooperates and we have cooperated many times, mostly defect but occasionally test
    if opp_c == 0 and my_c >= 8:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Probe against very cooperative opponents late in the match
    if my_c == n and opp_c >= n - 2 and n >= 50:
        if rng.random() < 0.1:
            return 'D'

    last_me, last_opp = history[-1]

    # Exploit if opponent cooperated after we defected
    if last_me == 'D' and last_opp == 'C':
        return 'D'

    # Recover from mutual defection
    if last_me == 'D' and last_opp == 'D':
        return 'C'

    # If we cooperated and opponent defected
    if last_me == 'C' and last_opp == 'D':
        # Defect only if opponent defected twice in a row while we cooperated on both
        if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
            return 'D'
        return 'C'

    # Default: cooperate
    return 'C'
